// Les clients à relancer quand ils n'ont rien publié depuis 14 jours. Adresse du site sans « / » final.
// « actif: false » pour mettre un client en pause (vacances, accord pour ne pas être relancé).
const CLIENTS = [
  // { nom: 'Opéria', prenom: 'Prénom', email: 'contact@exemple.fr', url: 'https://www.exemple.fr' },
];
return CLIENTS.filter((c) => c.actif !== false && /^https:\/\/[^\s/]+$/.test(c.url) && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email)).map((c) => ({ json: c }));

// Garde seulement les clients dont la dernière actualité date de plus de 14 jours (ou qui n'en ont aucune), et prépare l'e-mail.
// Modèle fixe, aucun texte écrit par une IA ; une idée d'actualité différente chaque semaine.
const clients = $('Clients suivis').all().map((i) => i.json), plans = $('Plan du site').all().map((i) => i.json);
const IDEES = [
  'un chantier qui démarre, avec 2 photos du lieu avant travaux et ce que le client vous a demandé',
  'une étape en cours, avec ce qui a été posé cette semaine et les matériaux utilisés',
  'une livraison, avec 3 photos du résultat, la surface et le délai',
  'un conseil du métier, à partir de la question que vos clients vous posent le plus souvent',
  'un nouveau produit, un nouvel horaire ou un changement dans l’équipe',
  'un avant/après, avec deux photos prises du même endroit',
];
const semaine = Math.floor(Date.now() / (7 * 864e5));
const sortie = [];
clients.forEach((c, i) => {
  const plan = plans[i] || {}, corps = String(plan.data ?? plan.body ?? '');
  if (+plan.statusCode !== 200 || !corps.includes('<urlset')) return; // site injoignable : la veille du lundi le signale déjà à Greg
  const dates = [...corps.matchAll(/<loc>[^<]*\/actualites\/[^<]+<\/loc><lastmod>(\d{4}-\d{2}-\d{2})<\/lastmod>/g)].map((m) => m[1]).sort();
  const derniere = dates[dates.length - 1];
  const jours = derniere ? Math.floor((Date.now() - Date.parse(derniere + 'T12:00:00Z')) / 864e5) : null;
  if (jours !== null && jours <= 14) return;
  const idee = IDEES[(semaine + i) % IDEES.length];
  const texte = `Bonjour ${c.prenom || ''},

${jours === null ? 'Votre site n’a pas encore d’actualité.' : `Votre dernière actualité date d’il y a ${jours} jours.`} Une courte publication toutes les une à deux semaines donne à Google de nouvelles pages à montrer, et à vos clients la preuve que l’entreprise est active.

Idée pour cette semaine : ${idee}.

Ça prend une minute depuis votre téléphone : ${c.url}/admin/ puis « Publier une actualité » tout en haut.

Si vous préférez, envoyez-moi simplement les photos et deux phrases en réponse à ce message : je m’en occupe.

Grégoire Muel
07 80 00 81 37`.replace('Bonjour ,', 'Bonjour,');
  sortie.push({ json: { a: c.email, sujet: 'Une actualité cette semaine pour votre site ?', texte } });
});
return sortie;
